<template><div class="page-heading"><div><div class="eyebrow">AUTOMATION</div><h1>自动化任务</h1><p>持久化定时任务、运行记录、失败重试与立即执行</p></div><div><el-button :icon="Clock" @click="recordsDialog=true">执行历史</el-button><el-button type="primary" :icon="Plus" @click="openCreate">创建任务</el-button></div></div><ResourceView ref="taskView" :config="config"/><el-dialog v-model="recordsDialog" title="任务执行历史" width="min(900px,calc(100vw - 28px))"><el-table :data="records" v-loading="recordsLoading" stripe><el-table-column prop="started_at" label="开始时间" width="165"><template #default="s">{{formatDate(s.row.started_at)}}</template></el-table-column><el-table-column prop="task_name" label="任务名称" min-width="145"/><el-table-column prop="trigger" label="触发方式" width="100"/><el-table-column prop="status" label="状态" width="90"><template #default="s"><el-tag :type="s.row.status==='success'?'success':s.row.status==='running'?'warning':'danger'" effect="dark">{{s.row.status}}</el-tag></template></el-table-column><el-table-column prop="duration_ms" label="耗时" width="90"><template #default="s">{{s.row.duration_ms??'—'}} ms</template></el-table-column><el-table-column prop="error" label="错误信息" min-width="190" show-overflow-tooltip/></el-table><div class="pagination-wrap"><span>共 {{recordsTotal}} 条</span><el-pagination v-model:current-page="recordsPage" :page-size="20" :total="recordsTotal" layout="prev,pager,next" @current-change="loadRecords"/></div></el-dialog></template>
<script setup lang="ts">
import { ref } from 'vue'
import { onMounted } from 'vue'
import { Clock, Plus } from '@element-plus/icons-vue'
import { api } from '../api'
import ResourceView from '../components/ResourceView.vue'
const taskView=ref(),recordsDialog=ref(false),records=ref<any[]>([]),recordsLoading=ref(false),recordsPage=ref(1),recordsTotal=ref(0)
function formatDate(v:string){return v?new Date(v).toLocaleString('zh-CN'):'—'}
function openCreate(){(taskView.value as any)?.openCreate()}
async function loadRecords(){recordsLoading.value=true;try{const {data}=await api.get('/tasks/records',{params:{page:recordsPage.value,page_size:20}});records.value=data.items||[];recordsTotal.value=data.total||0}finally{recordsLoading.value=false}}
onMounted(loadRecords)
const config={kicker:'AUTOMATION',title:'自动化任务',description:'持久化定时任务、运行记录、失败重试与立即执行',endpoint:'/tasks',itemName:'任务',nameKey:'name',keyword:'搜索任务',hideCreate:true,
  columns:[{key:'name',label:'任务名称',width:190},{key:'task_type',label:'任务类型',width:135,options:[{value:'github_check',label:'单仓库检查'},{value:'github_check_all',label:'全部仓库检查'},{value:'group_announcement',label:'定时群公告'},{value:'group_message',label:'定时群消息'},{value:'online_check',label:'在线状态检查'},{value:'ai_summary',label:'AI 总结'},{value:'health_check',label:'系统健康检查'},{value:'backup',label:'数据库备份'},{value:'push_retry',label:'失败推送重试'}]},{key:'schedule_kind',label:'调度模式',width:100,options:[{value:'interval',label:'间隔'},{value:'cron',label:'Cron'}]},{key:'interval_seconds',label:'执行间隔(秒)',width:110},{key:'enabled',label:'状态',type:'bool',width:80},{key:'last_status',label:'上次结果',type:'status',width:90},{key:'next_run_at',label:'下次执行',type:'date',width:165},{key:'total_runs',label:'执行次数',width:85}],
  createFields:[{key:'name',label:'任务名称',required:true},{key:'task_type',label:'任务类型',type:'select',required:true,options:[{value:'github_check',label:'检查指定仓库'},{value:'github_check_all',label:'检查所有仓库'},{value:'group_announcement',label:'定时群公告'},{value:'group_message',label:'定时群消息'},{value:'online_check',label:'机器人在线检查'},{value:'ai_summary',label:'AI 总结'},{value:'health_check',label:'系统健康检查'},{value:'backup',label:'数据库备份'},{value:'push_retry',label:'失败推送重试'}]},{key:'schedule_kind',label:'调度方式',type:'select',default:'interval',options:[{value:'interval',label:'固定间隔'},{value:'cron',label:'Cron 表达式'}]},{key:'interval_seconds',label:'间隔秒数（至少 30 秒）',type:'number',default:3600,min:30},{key:'cron_expr',label:'Cron 表达式',placeholder:'例如 0 9 * * *'},{key:'payload',label:'任务参数 JSON',type:'json',default:{},rows:5,placeholder:'例如 {"repository_id": 1}'},{key:'enabled',label:'启用任务',type:'switch',default:true},{key:'max_retries',label:'最大重试次数',type:'number',default:2,min:0,max:5},{key:'timeout_seconds',label:'超时时间（秒）',type:'number',default:300,min:10,max:3600}],
  editFields:[{key:'name',label:'任务名称'},{key:'schedule_kind',label:'调度方式',type:'select',options:[{value:'interval',label:'固定间隔'},{value:'cron',label:'Cron 表达式'}]},{key:'interval_seconds',label:'间隔秒数',type:'number',min:30},{key:'cron_expr',label:'Cron 表达式'},{key:'payload',label:'任务参数 JSON',type:'json',rows:5},{key:'enabled',label:'启用任务',type:'switch'},{key:'max_retries',label:'最大重试次数',type:'number',min:0,max:5},{key:'timeout_seconds',label:'超时时间（秒）',type:'number',min:10,max:3600}],
  actions:[{label:'立即运行',suffix:'run',method:'POST',type:'success',success:(d:any)=>d.message||'任务执行完成'},{labelFor:(r:any)=>r.enabled?'暂停':'启用',path:(r:any)=>`/tasks/${r.id}/toggle`,method:'POST',type:'warning'}],deletePath:'/tasks'}
</script>
